 $parent=(int)($_GET['supersedes']??0);$m=$b?final_count_meta($b):[];$data=$m['guided_input']??[];if(!$b&&$parent){$previous=count_batch($parent);final_count_owner($previous);if(!in_array($previous['status'],['Cancelled','Reversed'],true))throw new Exception('Close or reverse the previous adjustment first.');$data=final_count_meta($previous)['guided_input']??[];$data['count_date']=$previous['count_date'];$data['count_scope']=final_count_meta($previous)['count_scope']??'Sellable';}
