 echo '<div class="card guided-entry"><h3>Enter Inventory Count</h3><p class="ux-inline-guide">One final count. Validate first; stock changes only after Admin approval and posting. You may go back to correct errors before submission.</p><form method="post" action="inventory_count.php" enctype="multipart/form-data" class="stack" data-guided-entry data-initial-items="'.e(json_encode(array_values($items))).'"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="guided_validate"><input type="hidden" name="batch_id" value="'.(int)($b['id']??0).'"><input type="hidden" name="revision" value="'.(int)($b['revision']??0).'"><input type="hidden" name="supersedes" value="'.$parent.'"><div class="guided-fields"><label>Inventory Date<input type="date" name="'.($b?'display_date':'count_date').'" value="'.e($date).'" max="'.date('Y-m-d').'" '.($b?'disabled':'required').'></label><label>Count Scope<select name="'.($b?'display_scope':'count_scope').'" '.($b?'disabled':'').'><option value="Sellable" '.($scope==='Sellable'?'selected':'').'>Sellable Only</option><option value="All Conditions" '.($scope==='All Conditions'?'selected':'').'>All Stock Conditions</option></select></label></div>';
