function guided_event_details($event){$data=json_decode($event['details_json'],true)?:[];$out=[];foreach($data as $key=>$value){if(in_array($key,['digest','previous_digest','hash','rule'],true))continue;if($key==='previous_counts'){foreach($value as $row){$counts=$row['conditions']??[];if(!$counts)continue;$parts=[];foreach(['good'=>'Sellable','packaging'=>'Packaging','damaged'=>'Damaged','other'=>'Other'] as $k=>$label)$parts[]=$label.': '.(int)($counts[$k]??0);$out[]=e($row['sku']).' · '.e(implode(' / ',$parts));}}elseif($key==='errors'){foreach($value as $error)$out[]=e($error);}elseif(is_scalar($value)&&$value!=='')$out[]=e(ucwords(str_replace('_',' ',$key)).': '.(is_bool($value)?($value?'Yes':'No'):$value));}return $out?'<details><summary>View Details</summary><div class="muted small">'.implode('<br>',$out).'</div></details>':'—';}
function guided_count_history_list($tab){$where=$tab==='history'?"status IN ('Applied','Cancelled','Reversed')":"status NOT IN ('Applied','Cancelled','Reversed')";$attention=$_GET['attention']??'';$attentionWhere=['entry'=>"status IN ('Exported','Validated','Recounted')",'errors'=>"status='Error'",'approval'=>"status IN ('Submitted','Awaiting Approval')",'legacy'=>"status='Recount Required'"][$attention]??'';if($attentionWhere){$where.=' AND '.$attentionWhere;if(current_user()['role']!=='Admin')$where.=' AND created_by='.(int)current_user()['id'];}$search=trim((string)($_GET['search']??''));$args=['%'.$search.'%','%'.$search.'%'];$where.=' AND (batch_ref LIKE ? OR created_name LIKE ?)';$total=rs8_list_total('SELECT COUNT(*) FROM inventory_count_batches WHERE '.$where,$args);$offset=min(max(0,intdiv((int)($_GET['offset']??0),10)*10),max(0,(int)ceil($total/10)-1)*10);$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE '.$where.' ORDER BY id DESC LIMIT 10 OFFSET '.$offset);$q->execute($args);echo '<div class="card"><form method="get" class="inline-form"><input type="hidden" name="page" value="inventory_count"><input type="hidden" name="tab" value="'.e($tab).'"><input type="hidden" name="attention" value="'.e($attention).'"><input name="search" value="'.e($search).'" aria-label="Adjustment reference or preparer" placeholder="Reference / Prepared by"><button class="btn secondary">Search</button></form><div class="guided-manual-table"><table class="table"><thead><tr><th>Reference</th><th>Inventory Date</th><th>Status</th><th>Prepared By</th><th>Reviewer</th><th>Approver</th><th></th></tr></thead><tbody>';foreach($q as $row)echo '<tr><td>'.e($row['batch_ref']).'</td><td>'.e($row['count_date']).'</td><td>'.e(guided_status($row)).'</td><td>'.e($row['created_name']).'</td><td>'.e($row['reviewed_name']?:'Pending').'</td><td>'.e($row['approved_name']?:'Pending').'</td><td><a class="btn ghost sm" href="?page=inventory_count&id='.$row['id'].'">View</a></td></tr>';if(!$total)echo '<tr><td colspan="7">No adjustments match this view.</td></tr>';echo '</tbody></table></div></div>';echo rs8_pagination($total,$offset,10,array_replace($_GET,['page'=>'inventory_count','tab'=>$tab]));}
echo '<div class="page-head"><div><h1>Inventory Adjustments</h1><p>Enter Count → Validate &amp; Review → Submit to Admin → Approval &amp; Posting</p></div><a class="btn ghost" href="?page=reports&report=adjustments">Adjustment Reports</a></div>';
try{
 $b=$id?count_batch($id):null;$meta=$b?final_count_meta($b):[];$tab=$_GET['tab']??'count';$edit=$b&&isset($_GET['edit'])&&in_array($b['status'],['Exported','Error','Validated'],true);$owner=$b&&can_action('upload_inventory_count')&&(current_user()['role']==='Admin'||(int)$b['created_by']===current_user()['id']);$entry=(!$b&&in_array($tab,['count','manual'],true))||$edit;
