 echo '<div class="guided-manual-table"><table class="table"><thead><tr><th>Product / Master SKU</th><th>System Quantity<br>at Count Date</th><th>Actual Count</th><th>Variance</th></tr></thead><tbody>';$counted=0;foreach(count_lines($id) as $line){if($line['actual_count']===null)continue;$counted++;$snap=json_decode($line['snapshot_conditions'],true);$actual=json_decode($line['final_conditions'],true);$system=$scope==='Sellable'?$snap['good']:array_sum($snap);$count=$scope==='Sellable'?$actual['good']:array_sum($actual);echo '<tr><td>'.e($line['product_name']).'<br><span class="muted small">'.e($line['master_sku']).'</span>'.($scope==='All Conditions'?'<div class="muted small">Sellable / Packaging / Damaged / Other<br>System: '.e(implode(' / ',array_values($snap))).'<br>Counted: '.e(implode(' / ',array_values($actual))).'</div>':'').'</td><td>'.$system.'</td><td>'.$count.'</td><td class="'.($count<$system?'guided-shortage':'').'">'.($count>$system?'+':'').($count-$system).'</td></tr>';}if(!$counted)echo '<tr><td colspan="4">No valid count lines available.</td></tr>';echo '</tbody></table></div><p class="muted small">Reason: '.e($b['reason']).'<br>Supporting Reference: '.e($b['support_reference']).'</p>';
