 if(in_array($b['status'],['Submitted','Awaiting Approval'],true)&&current_user()['role']!=='Admin')echo '<div class="alert info">Submitted to Admin for review and approval. Stocks remain unchanged until posting.</div>';
 $plans=$plan?$plan['lines']:array_values(array_filter(array_map(fn($l)=>json_decode($l['posting_json']??'null',true),count_lines($id))));
